import unittest
from dataclasses import FrozenInstanceError

from solution import DivisionResult, divide_integer_text


class DivideIntegerTextTests(unittest.TestCase):
    def test_valid_division(self):
        self.assertEqual(divide_integer_text("7", "2"), DivisionResult("ok", 3.5, ""))
        self.assertEqual(divide_integer_text("-9", "+3"), DivisionResult("ok", -3.0, ""))

    def test_surrounding_whitespace_and_integer_syntax(self):
        self.assertEqual(
            divide_integer_text("  +1_000\n", "\t4 "),
            DivisionResult("ok", 250.0, ""),
        )

    def test_zero_denominator(self):
        expected = DivisionResult("zero", None, "denominator must not be zero")
        self.assertEqual(divide_integer_text("5", "0"), expected)
        self.assertEqual(divide_integer_text("5", " -0 "), expected)

    def test_empty_or_malformed_input(self):
        expected = DivisionResult("invalid", None, "both inputs must be integers")
        cases = [
            ("", "1"),
            ("   ", "1"),
            ("1.5", "2"),
            ("ten", "2"),
            ("2", "3x"),
            ("0x10", "2"),
        ]
        for numerator, denominator in cases:
            with self.subTest(numerator=numerator, denominator=denominator):
                self.assertEqual(divide_integer_text(numerator, denominator), expected)

    def test_non_string_arguments_raise_type_error(self):
        for numerator, denominator in [(1, "2"), ("1", 2), (None, "1"), ("1", None)]:
            with self.subTest(numerator=numerator, denominator=denominator):
                with self.assertRaises(TypeError):
                    divide_integer_text(numerator, denominator)

    def test_quotient_float_overflow(self):
        huge = "1" + ("0" * 10000)
        self.assertEqual(
            divide_integer_text(huge, "1"),
            DivisionResult("overflow", None, "result is outside float range"),
        )
        self.assertEqual(
            divide_integer_text("-" + huge, "1"),
            DivisionResult("overflow", None, "result is outside float range"),
        )

    def test_result_dataclass_is_frozen(self):
        result = DivisionResult("ok", 1.0, "")
        with self.assertRaises(FrozenInstanceError):
            result.kind = "invalid"


if __name__ == "__main__":
    unittest.main()

